// Fixed page and checksum independently reproduced once by installed libogg
// ogg_page_checksum_set, not by this parser or the design fixture CRC routine.
// Its provenance/digest is retained in dist/r18-voice-proof/crc-independent.json.
// Tests have no libogg/runtime oracle dependency.
func TestVoiceOggCRCIndependentVector(t *testing.T) {
	data, _ := hex.DecodeString("4f676753000200000000000000001818181800000000c3c6153d01134f707573486561640101000080bb0000000000")
	if got := oggCRC(data); got != 0x3d15c6c3 {
		t.Fatalf("Ogg CRC=%08x", got)
	}
	data[22] ^= 0xff
	if oggCRC(data) != 0x3d15c6c3 {
		t.Fatal("CRC field must be treated as zero")
	}
	data[len(data)-1] ^= 1
	if oggCRC(data) == 0x3d15c6c3 {
		t.Fatal("body not covered")
	}
}

func TestVoiceOggLocalQuotaBoundaries(t *testing.T) {
	data, _ := hex.DecodeString("4f676753000200000000000000001818181800000000c3c6153d01134f707573486561640101000080bb00000000004f67675300000000000000000000181818180100000085270dd201194f707573546167730900000073796e746865746963000000004f6767530004c0030000000000001818181802000000ab9a09300101f8")
	cases := []struct {
		name  string
		limit func(*oggOpusLimits, int)
	}{
		{"file", func(v *oggOpusLimits, delta int) { v.file = len(data) + delta }},
		{"tags", func(v *oggOpusLimits, delta int) { v.tags = 25 + delta }},
		{"packet", func(v *oggOpusLimits, delta int) { v.packet = 1 + delta }},
		{"pages", func(v *oggOpusLimits, delta int) { v.pages = uint64(3 + delta) }},
		{"packets", func(v *oggOpusLimits, delta int) { v.packets = uint64(1 + delta) }},
		{"samples", func(v *oggOpusLimits, delta int) { v.samples = uint64(960 + delta) }},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			limits := voiceOggLimits
			c.limit(&limits, 0)
			if _, err := inspectOggOpus(t.Context(), data, limits); err != nil {
				t.Fatal("at local limit", err)
			}
			c.limit(&limits, -1)
			_, err := inspectOggOpus(t.Context(), data, limits)
			var failure *OggOpusError
			if !errors.As(err, &failure) || failure.Code != "quota" {
				t.Fatal("one over local limit", err)
			}
		})
	}
	ctx, cancel := context.WithCancel(t.Context())
	cancel()
	if _, err := InspectOggOpus(ctx, data); !errors.Is(err, context.Canceled) {
		t.Fatal(err)
	}
}

func TestVoiceOpusFramingNonemptyAndEdges(t *testing.T) {
	cases := []struct {
		name    string
		data    []byte
		samples uint64
	}{
		{"one nonempty", []byte{0xf8, 0xff, 0xfe}, 960},
		{"two CBR nonempty", []byte{0xf9, 1, 2, 3, 4}, 1920},
		{"two VBR nonempty", []byte{0xfa, 1, 2, 3, 4}, 1920},
		{"three CBR nonempty", []byte{0xfb, 3, 1, 2, 3}, 2880},
		{"three VBR nonempty", []byte{0xfb, 0x83, 1, 2, 1, 2, 3, 4}, 2880},
		{"padding254 terminates", append([]byte{0xfb, 0x41, 254, 0xff}, make([]byte, 254)...), 960},
		{"padding255 extends", append([]byte{0xfb, 0x41, 255, 0, 0xff}, make([]byte, 254)...), 960},
		{"padding nonzero accepted", []byte{0xfb, 0x41, 1, 0xff, 0xfe}, 960},
		{"length251", append([]byte{0xfa, 251}, make([]byte, 251)...), 1920},
		{"length252 second byte", append([]byte{0xfa, 252, 0}, make([]byte, 252)...), 1920},
		{"max frame", append([]byte{0xf8}, make([]byte, 1275)...), 960},
		{"max120ms", []byte{0xfb, 6}, 5760},
		{"48 shortest frames", []byte{0x83, 48}, 5760},
		{"SILK60ms", []byte{0x18}, 2880},
		{"hybrid20ms", []byte{0x68}, 960},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			n, err := opusPacketSamples(c.data)
			if err != nil || n != c.samples {
				t.Fatal(n, err)
			}
		})
	}
	for _, data := range [][]byte{nil, {0xf9, 1}, {0xfa, 252}, {0xfa, 1}, {0xfb}, {0xfb, 0}, {0xfb, 7}, {0x83, 49}, {0xfb, 0x41, 255}, {0xfb, 0x41, 2, 0}, {0xfb, 0x83, 1}, {0xfb, 0x82, 5, 0}, {0xfb, 3, 0}, append([]byte{0xf8}, make([]byte, 1276)...)} {
		if _, err := opusPacketSamples(data); err == nil {
			t.Fatalf("invalid framing accepted %x", data[:min(len(data), 8)])
		}
	}
}

func FuzzVoiceOpusFraming(f *testing.F) {
	for _, p := range [][]byte{{0xf8, 0xff, 0xfe}, {0xfb, 0x83, 1, 1, 0, 0, 0}, {0xfb, 0x41, 255, 0}, {0xfa, 252, 0}, {0x83, 48}} {
		f.Add(p)
	}
	f.Fuzz(func(t *testing.T, p []byte) {
		if len(p) > 61440 {
			t.Skip()
		}
		n, err := opusPacketSamples(p)
		if err == nil && (n == 0 || n > 5760 || n%120 != 0) {
			t.Fatal(n)
		}
	})
}
